import csv, json, re, sqlite3, unicodedata
from datetime import datetime

dq = {"invalid_emails": [], "date_format_issues": [], "encoding_issues_fixed": [], "corrupt_records_skipped": []}
records = []  # dicts with source, id, fields

def norm_date(d, rid):
    d = (d or "").strip()
    if not d: return d
    m = re.match(r'^(\d{1,2})/(\d{1,2})/(\d{4})$', d)
    if m:
        nd = f"{m.group(3)}-{int(m.group(1)):02d}-{int(m.group(2)):02d}"
        dq["date_format_issues"].append({"record_id": rid, "original_value": d, "normalized_to": nd})
        return nd
    return d

COUNTRY = {"USA": "US", "United States": "US", "U.S.": "US", "U.S.A.": "US"}
def norm_country(c):
    c = (c or "").strip()
    return COUNTRY.get(c, c)

# --- mainframe ---
widths = [8,20,20,40,15,45,30,2,5,3,10]
fnames = ["customer_id","first_name","last_name","email","phone","address","city","state","zip","country","signup_date"]
for line in open("/app/customers_mainframe.dat"):
    line = line.rstrip("\n")
    if len(line) != 198:
        rid = line[:8].strip() or "UNKNOWN"
        dq["corrupt_records_skipped"].append({"source": "mainframe", "record_id": rid, "reason": "wrong line length"})
        continue
    parts, i = [], 0
    for w in widths:
        parts.append(line[i:i+w].strip()); i += w
    rec = dict(zip(fnames, parts))
    rec["country"] = norm_country(rec["country"])
    records.append({"source": "mainframe", "id": rec.pop("customer_id"), **rec})

# --- crm ---
def fix_enc(s):
    if s and any(ch in s for ch in "ÃÂâ"):
        try:
            return s.encode("latin-1").decode("utf-8")
        except Exception:
            return s
    return s

with open("/app/customers_crm.csv", newline="", encoding="utf-8") as f:
    rdr = csv.DictReader(f)
    for row in rdr:
        rid = row["customer_id"]
        if row is None or None in row.values():
            dq["corrupt_records_skipped"].append({"source": "crm", "record_id": rid, "reason": "malformed row"})
            continue
        if not (row.get("email") or "").strip() and not (row.get("phone") or "").strip():
            dq["corrupt_records_skipped"].append({"source": "crm", "record_id": rid, "reason": "malformed row: missing required fields"})
            continue
        enc_fields = []
        rec = {}
        for k in fnames[1:]:
            v = (row.get(k) or "").strip()
            nv = fix_enc(v)
            if nv != v: enc_fields.append(k)
            rec[k] = nv
        if enc_fields:
            dq["encoding_issues_fixed"].append({"record_id": rid, "fields": enc_fields})
        rec["first_name"] = re.sub(r'^(Mr|Mrs|Ms|Dr|Prof)\.\s+', '', rec["first_name"])
        rec["signup_date"] = norm_date(rec["signup_date"], rid)
        rec["country"] = norm_country(rec["country"])
        records.append({"source": "crm", "id": rid, **rec})

# --- web ---
def pick(d, *keys):
    for k in keys:
        if k in d and d[k] not in (None, ""):
            return d[k]
    return ""
for line in open("/app/customers_web.jsonl"):
    line = line.strip()
    if not line: continue
    try:
        d = json.loads(line)
    except Exception:
        m = re.search(r'"customer[Ii]d"\s*:\s*"([^"]+)"', line)
        dq["corrupt_records_skipped"].append({"source": "web", "record_id": m.group(1) if m else "UNKNOWN", "reason": "invalid JSON"})
        continue
    name = d.get("name") or {}
    rec = {
        "first_name": pick(d, "firstName", "first_name") or pick(name, "given", "first", "first_name"),
        "last_name": pick(d, "lastName", "last_name") or pick(name, "surname", "last", "last_name"),
        "email": pick(d, "email"),
        "phone": pick(d, "phoneNumber", "phone"),
        "address": pick(d, "streetAddress", "address"),
        "city": pick(d, "city"),
        "state": pick(d, "state", "state_province"),
        "zip": str(pick(d, "postalCode", "zip", "zip_code")),
        "country": norm_country(pick(d, "country")),
        "signup_date": norm_date(pick(d, "signupDate", "signup_date"), pick(d, "customerId", "customer_id")),
    }
    records.append({"source": "web", "id": pick(d, "customerId", "customer_id"), **rec})

# --- support ---
con = sqlite3.connect("/app/customers_support.db")
for row in con.execute("SELECT id,first_name,last_name,email,phone,address,city,state,zip,country,signup_date FROM customers"):
    rec = dict(zip(fnames, row))
    rec["country"] = norm_country(rec["country"])
    records.append({"source": "support", "id": rec.pop("customer_id"), **{k: (v or "") for k, v in rec.items()}})

# invalid emails
def valid_email(e):
    return bool(e) and "@" in e
for r in records:
    if r["email"] and not valid_email(r["email"]):
        dq["invalid_emails"].append(r["email"])

# --- dedup: union-find ---
n = len(records)
parent = list(range(n))
def find(x):
    while parent[x] != x:
        parent[x] = parent[parent[x]]; x = parent[x]
    return x
def union(a, b):
    ra, rb = find(a), find(b)
    if ra != rb: parent[ra] = rb

def strip_acc(s):
    return "".join(c for c in unicodedata.normalize("NFKD", s) if not unicodedata.combining(c))
def norm_name(r):
    return (strip_acc(r["first_name"]) + " " + strip_acc(r["last_name"])).strip().lower()
def addr_key(a):
    a = strip_acc(a.lower())
    a = re.sub(r'[^a-z0-9 ]', ' ', a)
    toks = a.split()
    if len(toks) >= 2: return toks[0] + "|" + toks[1]
    return " ".join(toks)

by_email, by_phone, by_na = {}, {}, {}
for i, r in enumerate(records):
    e = r["email"].strip().lower()
    if valid_email(e):
        if e in by_email: union(i, by_email[e])
        else: by_email[e] = i
    ph = re.sub(r'\D', '', r["phone"])
    if ph:
        if ph in by_phone: union(i, by_phone[ph])
        else: by_phone[ph] = i
    nm = norm_name(r)
    ak = addr_key(r["address"])
    if nm.strip() and ak:
        k = (nm, ak)
        if k in by_na: union(i, by_na[k])
        else: by_na[k] = i

groups = {}
for i in range(n):
    groups.setdefault(find(i), []).append(i)

SRC_ORDER = {"mainframe": 0, "crm": 1, "web": 2, "support": 3}
def dkey(r):
    try: return datetime.strptime(r["signup_date"], "%Y-%m-%d")
    except Exception: return datetime.min

group_list = sorted(groups.values(), key=lambda g: min(g))
unified, report = [], {}
fields = ["first_name","last_name","email","phone","address","city","state","zip","country","signup_date"]
for idx, g in enumerate(group_list, 1):
    uid = f"U{idx:04d}"
    recs = sorted((records[i] for i in g), key=lambda r: dkey(r), reverse=True)
    merged = {}
    for f in fields:
        merged[f] = next((r[f] for r in recs if r[f]), "")
    srcs = sorted({r["source"] for r in recs}, key=lambda s: SRC_ORDER[s])
    unified.append({"unified_id": uid, **{f: merged[f] for f in fields}, "source_systems": ",".join(srcs)})
    report[uid] = {"merged_from": [records[i]["id"] for i in sorted(g, key=lambda i: (SRC_ORDER[records[i]["source"]], records[i]["id"]))], "email": merged["email"]}

with open("/app/customers_unified.csv", "w", newline="") as f:
    w = csv.DictWriter(f, fieldnames=["unified_id"] + fields + ["source_systems"])
    w.writeheader()
    w.writerows(unified)

with open("/app/dedup_report.json", "w") as f:
    json.dump(report, f, indent=2)

dq_out = {k: v for k, v in dq.items() if v}
dq_out["total_issues_found"] = sum(len(v) for v in dq.values())
with open("/app/data_quality_report.json", "w") as f:
    json.dump(dq_out, f, indent=2)

print(f"records={len(records)} unified={len(unified)}")
print(json.dumps(dq_out, indent=2))
EOF
